import React from 'react';

const QuestionDisplay = ({ question }) => {
    return (
        <div className="question-display">
            <h2>{question.text}</h2>
        </div>
    );
};

const quizData = [
    {
        text: "What is the capital of France?",
        answers: ["Paris", "London", "Berlin", "Madrid"],
        correct: "Paris",
    },
    {
        text: "What is 2 + 2?",
        answers: ["3", "4", "5", "6"],
        correct: "4",
    },
    // Add more questions here
];

export default quizData;
